/* @author MILO-GAO(高振銘)@2020 */ package page2020.unit;import java.util.ArrayList;import java.util.List;import page2020.core.Name;public class Menu extends Name<Menu> {	private String sysCode;	private String parent;	private int level;	private String code;	private List<Func> funcList = new ArrayList<Func>();	private List<Menu> children = new ArrayList<Menu>();	@Override	public Menu copy() {		Menu menu = super.copy();		List<Func> funcList = new ArrayList<Func>();		int size = this.getFuncList().size();		for (int i=0; i < size; i++) {			funcList.add(this.funcList.get(i).copy());		}		menu.setFuncList(funcList);		List<Menu> menuList = new ArrayList<Menu>();		size = this.getChildren().size();		for (int i=0; i < size; i++) {			menuList.add(this.children.get(i).copy());		}		menu.setChildren(menuList);		return menu;	}	@Override	public String toString() {		return "Menu [sysCode=" + sysCode + ", parent=" + parent + ", level=" + level + ", code=" + code + "]";	}		public String getSysCode() {		return sysCode;	}	public void setSysCode(String sysCode) {		this.sysCode = sysCode;	}	public String getParent() {		return parent;	}	public void setParent(String parent) {		this.parent = parent;	}	public int getLevel() {		return level;	}	public void setLevel(int level) {		this.level = level;	}	public String getCode() {		return code;	}	public void setCode(String code) {		this.code = code;	}	public List<Func> getFuncList() {		return funcList;	}	public void setFuncList(List<Func> funcList) {		this.funcList = funcList;	}	public List<Menu> getChildren() {		return children;	}	public void setChildren(List<Menu> children) {		this.children = children;	}}